using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class Ramps162{static void Add(Transform root,Vector3 a,Vector3 b){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);SceneManager.MoveGameObjectToScene(o,root.gameObject.scene);o.name="Smooth_Stair_Collision";o.transform.SetParent(root,false);o.transform.localPosition=(a+b)*.5f-Vector3.up*.09f;o.transform.localRotation=Quaternion.LookRotation(b-a);o.transform.localScale=new Vector3(2.8f,.18f,(b-a).magnitude+.08f);o.GetComponent<Renderer>().enabled=false;}public static string Main(){var s=SceneManager.GetSceneByPath("Assets/Scenes/TreeHouseVariantsWorkshop.unity");var roots=s.GetRootGameObjects().Where(r=>r.name.StartsWith("0")&&!r.name.StartsWith("00")).OrderBy(r=>r.name).ToArray();foreach(var r in roots)foreach(var t in r.GetComponentsInChildren<Transform>().Where(t=>t.name=="Stair_Tread"))t.GetComponent<Collider>().enabled=false;
Add(roots[0].transform,new Vector3(0,.2f,-16),new Vector3(0,4.8f,-5.5f));Add(roots[1].transform,new Vector3(-9,.2f,-16),new Vector3(-9,2.5f,-10));Add(roots[1].transform,new Vector3(-4,2.5f,-9),new Vector3(-4,4.8f,-5.5f));Add(roots[2].transform,new Vector3(7,.2f,-15),new Vector3(7,3,-7.5f));
foreach(var r in roots)PrefabUtility.SaveAsPrefabAsset(r,"Assets/Prefabs/Workshop/TreeHousePrototypes/"+r.name+".prefab");EditorSceneManager.SaveScene(s);return "Smoothed stair collisions";}}
